import java.util.ArrayList;
import java.util.List;

class Variance {
    static void demo() {
        List<String> names = new ArrayList<>();
        // List<Object> objects = names;       // error: invariant
        List<? extends Object> view = names;   // OK: a read-only view, written at the use site
        Object first = view.isEmpty() ? null : view.get(0);

        String[] currencies = { "EUR" };
        Object[] objects = currencies;         // OK: arrays are covariant
        objects[0] = 978;                      // compiles, throws ArrayStoreException
    }
}

