interface Payment { long cents(); }
record CardPayment(long cents) implements Payment {}
record FeePayment(long cents) implements Payment {}

static void addProcessingFee(List<Payment> batch) {
    batch.add(new FeePayment(batch.stream().mapToLong(Payment::cents).sum() / 100));
}

List<CardPayment> cards = new ArrayList<>(List.of(new CardPayment(1_200)));
addProcessingFee(cards);
// error: incompatible types: List<CardPayment> cannot be converted to List<Payment>

static FeePayment processingFee(List<? extends Payment> batch) {
    return new FeePayment(batch.stream().mapToLong(Payment::cents).sum() / 100);
}

FeePayment fee = processingFee(cards);           // compiles: ? extends makes it a read-only view
List<Payment> ledgerLines = new ArrayList<>();
ledgerLines.addAll(cards);
ledgerLines.add(fee);

